// Command gen emits the Go-derived test vectors for the TypeScript legal
// evaluator (server/static/src/engine/legal). Everything it writes comes out
// of the real Go implementation - package legal's catalog, package
// boardgame's plan engine, and the example games - so the checked-in JSON is
// what the TypeScript must reproduce.
//
// Regenerate from the repository root with:
//
//	./scripts/go-local run ./server/static/src/engine/legal/testdata/gen
//
// It imports the repository's packages and changes none of them. Output is
// deterministic (fixed game id and secret salt, sorted keys), so a diff in
// the JSON means the Go semantics changed.
package main

import (
	"bytes"
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"runtime"
	"sort"

	"github.com/jkomoros/boardgame"
)

const generatedComment = "GENERATED by server/static/src/engine/legal/testdata/gen from the real Go implementation. Do not edit; regenerate with: ./scripts/go-local run ./server/static/src/engine/legal/testdata/gen"

func compactJSON(in []byte) []byte {
	var buf bytes.Buffer
	must(json.Compact(&buf, in), "compacting json")
	return buf.Bytes()
}

func marshal(v interface{}) []byte {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	// The corpus spells operators like ">=" literally; keep them readable.
	enc.SetEscapeHTML(false)
	must(enc.Encode(v), "marshaling")
	return bytes.TrimRight(buf.Bytes(), "\n")
}

// writeLines writes a JSON object whose top-level keys each hold an array or
// object, one element per line: small enough to diff, without the 10x blowup
// of full indentation on state records.
func writeLines(path string, sections []section) {
	var buf bytes.Buffer
	buf.WriteString("{\n")
	for i, s := range sections {
		buf.WriteString(string(marshal(s.key)) + ": ")
		switch {
		case s.scalar != nil:
			buf.Write(marshal(s.scalar))
		case s.list != nil:
			buf.WriteString("[\n")
			for j, item := range s.list {
				buf.Write(marshal(item))
				if j < len(s.list)-1 {
					buf.WriteString(",")
				}
				buf.WriteString("\n")
			}
			buf.WriteString("]")
		default:
			buf.WriteString("{\n")
			keys := make([]string, 0, len(s.object))
			for k := range s.object {
				keys = append(keys, k)
			}
			sort.Strings(keys)
			for j, k := range keys {
				buf.WriteString(string(marshal(k)) + ": ")
				buf.Write(marshal(s.object[k]))
				if j < len(keys)-1 {
					buf.WriteString(",")
				}
				buf.WriteString("\n")
			}
			buf.WriteString("}")
		}
		if i < len(sections)-1 {
			buf.WriteString(",")
		}
		buf.WriteString("\n")
	}
	buf.WriteString("}\n")
	must(os.WriteFile(path, buf.Bytes(), 0644), "writing "+path)
	fmt.Printf("wrote %s (%d bytes)\n", path, buf.Len())
}

type section struct {
	key    string
	scalar interface{}
	list   []interface{}
	object map[string]interface{}
}

func anyList[T any](in []T) []interface{} {
	out := make([]interface{}, len(in))
	for i, v := range in {
		out[i] = v
	}
	return out
}

func anyMap[T any](in map[string]T) map[string]interface{} {
	out := make(map[string]interface{}, len(in))
	for k, v := range in {
		out[k] = v
	}
	return out
}

func main() {
	_, self, _, _ := runtime.Caller(0)
	genDir := filepath.Dir(self)
	outDir := flag.String("out", filepath.Dir(genDir), "directory to write the JSON vectors into")
	repoRoot := filepath.Clean(filepath.Join(genDir, "..", "..", "..", "..", "..", "..", ".."))
	corpusDir := flag.String("corpus", filepath.Join(repoRoot, "legal", "testdata", "conformance"), "the conformance corpus directory")
	flag.Parse()

	fixtures := &fixtureCache{built: map[string]fixture{}}
	vectors := buildVectors(*corpusDir, fixtures)
	plans := buildPlans()
	evaluable := buildEvaluable()

	exportedFixtures := map[string]exportedFixture{}
	games := map[string]exportedGame{}
	managers := map[string]*boardgame.GameManager{}
	for name, f := range fixtures.built {
		exportedFixtures[name] = exportFixture(f)
		managers[f.gameKey] = f.game.Manager()
	}
	for gameKey, manager := range managers {
		games[gameKey] = exportGame(gameKey, manager)
	}
	for name, f := range plans.fixtures {
		exportedFixtures[name] = f
	}
	for name, g := range plans.games {
		games[name] = g
	}
	for name, f := range evaluable.fixtures {
		exportedFixtures[name] = f
	}
	for name, g := range evaluable.games {
		games[name] = g
	}

	writeLines(filepath.Join(*outDir, "fixtures.json"), []section{
		{key: "comment", scalar: generatedComment},
		{key: "games", object: anyMap(games)},
		{key: "fixtures", object: anyMap(exportedFixtures)},
	})
	writeLines(filepath.Join(*outDir, "vectors.json"), []section{
		{key: "comment", scalar: generatedComment},
		{key: "shape", scalar: "vectors[i] = [source, index into specs (and predicates), fixture name in fixtures.json, proposer, index into verdicts]"},
		{key: "specs", list: anyList(vectors.Specs)},
		{key: "predicates", list: anyList(vectors.Predicates)},
		{key: "verdicts", list: anyList(vectors.Verdicts)},
		{key: "constructorErrors", list: anyList(vectors.ConstructorErrors)},
		{key: "vectors", list: anyList(vectors.Vectors)},
	})
	writeLines(filepath.Join(*outDir, "plans.json"), plans.sections())
	writeLines(filepath.Join(*outDir, "evaluable.json"), evaluable.sections())
}
